-- JobHub — নতুন ৬০ দিনের BCS স্টাডি রুটিন (দিন ১ = 2026-11-23)

-- পুরোনো সক্রিয় রুটিন: রেফারেন্সবিহীন রো মুছে, রেফারেন্সড রো আর্কাইভ করা হয়।

begin;


delete from public.routines r
where r.archived_at is null
  and not exists (select 1 from public.exam_schedules es where es.routine_id = r.id)
  and not exists (select 1 from public.routine_progress rp where rp.routine_id = r.id);

update public.routines r
set archived_at = now(), status = 'archived'
where r.archived_at is null;


on conflict (course_id, kind, routine_date, subject_id, topic_id) do update set
  title_bn = excluded.title_bn, focus_note_bn = excluded.focus_note_bn,
  slot_label = excluded.slot_label, target_bn = excluded.target_bn,
  task_kind = excluded.task_kind, minutes = excluded.minutes,
  week_index = excluded.week_index, status = 'published', archived_at = null,
  updated_at = now();

on conflict (course_id, kind, routine_date, subject_id, topic_id) do update set
  title_bn = excluded.title_bn, focus_note_bn = excluded.focus_note_bn,
  slot_label = excluded.slot_label, target_bn = excluded.target_bn,
  task_kind = excluded.task_kind, minutes = excluded.minutes,
  week_index = excluded.week_index, status = 'published', archived_at = null,
  updated_at = now();

on conflict (course_id, kind, routine_date, subject_id, topic_id) do update set
  title_bn = excluded.title_bn, focus_note_bn = excluded.focus_note_bn,
  slot_label = excluded.slot_label, target_bn = excluded.target_bn,
  task_kind = excluded.task_kind, minutes = excluded.minutes,
  week_index = excluded.week_index, status = 'published', archived_at = null,
  updated_at = now();

on conflict (course_id, kind, routine_date, subject_id, topic_id) do update set
  title_bn = excluded.title_bn, focus_note_bn = excluded.focus_note_bn,
  slot_label = excluded.slot_label, target_bn = excluded.target_bn,
  task_kind = excluded.task_kind, minutes = excluded.minutes,
  week_index = excluded.week_index, status = 'published', archived_at = null,
  updated_at = now();

on conflict (course_id, kind, routine_date, subject_id, topic_id) do update set
  title_bn = excluded.title_bn, focus_note_bn = excluded.focus_note_bn,
  slot_label = excluded.slot_label, target_bn = excluded.target_bn,
  task_kind = excluded.task_kind, minutes = excluded.minutes,
  week_index = excluded.week_index, status = 'published', archived_at = null,
  updated_at = now();

commit;
